		if (clause->variables == NULL)
			ereport(ERROR,
					(errcode(PG_ERRCODE_SYNTAX_ERROR),
					 errmsg("SUCH THAT requires a DECIDE clause; declare the decision variables with DECIDE"),
					 parser_errposition(body_location)));
