	PGDecideSpan *entry;

	if (!extra->in_decide_clause || anchor < 0 || span.start < 0)
		return;
	entry = (PGDecideSpan *) palloc(sizeof(PGDecideSpan));
	entry->anchor = anchor;
	entry->role = role;
	entry->start = span.start;
	entry->end = span.end;
	entry->node = NULL;
