/*
 * DeciDB: the span of one expression, keyed by the node that stands for it. The transformer gives the node's parsed
 * expression a query location, which is how a message finds the text. A node returned by several reductions (a
 * flattened AND, a negated constant) keeps the last, the widest; a parenthesized one keeps the span inside the
 * parentheses (noteDecideParen).
 */
static PGNode *
noteDecideExpr(PGNode *expr, YYLTYPE span, core_yyscan_t yyscanner)
{
	base_yy_extra_type *extra = pg_yyget_extra(yyscanner);
	PGDecideSpan *entry;

	if (expr == extra->decide_paren_node)
	{
		extra->decide_paren_node = NULL;
		return expr;
	}
	if (!extra->in_decide_clause || !expr || span.start < 0)
		return expr;
	entry = (PGDecideSpan *) palloc(sizeof(PGDecideSpan));
	entry->anchor = -1;
	entry->role = PG_DECIDE_SPAN_EXPR;
	entry->start = span.start;
	entry->end = span.end;
	entry->node = expr;
	extra->decide_spans = lappend(extra->decide_spans, entry);
	return expr;
}

/* DeciDB: `(e)` returns e itself; the decorator above would span the parentheses, so it skips this node once. */
static PGNode *
noteDecideParen(PGNode *expr, core_yyscan_t yyscanner)
{
	pg_yyget_extra(yyscanner)->decide_paren_node = expr;
	return expr;
}

/*
 * DeciDB: the key of a reducer's own `per`, anchored at the location the reducer is bound at: the BY when it has one,
 * else the call. The key's text is the reducer's own, whichever way another clause spells the same key.
 */
static void
noteDecideReducerKey(PGNode *scope_node, int anchor, core_yyscan_t yyscanner)
{
	PGDecideScope *scope = (PGDecideScope *) scope_node;
	YYLTYPE key;

	if (scope->per != PG_DECIDE_PER_KEY)
		return;
	key.start = scope->key_start;
	key.end = scope->key_end;
	noteDecideSpan(yyscanner, anchor, PG_DECIDE_SPAN_PER, key);
}

/*
 * DeciDB: a reducer's call without its BY, anchored at the BY. The span runs from the start of the call to the end of
 * its closing parenthesis; `call_start` is that of the call when the call is built by this rule (the scoped and the
 * colon form), else `call_end` is the whole call (`func_application`).
 */
static void
noteDecideCall(YYLTYPE call_end, YYLTYPE by, core_yyscan_t yyscanner, YYLTYPE call_start)
{
	YYLTYPE call = call_end;

	if (call_start.start != 0 || call_start.end != 0)
		call.start = call_start.start;
	noteDecideSpan(yyscanner, by.start, PG_DECIDE_SPAN_CALL, call);
}

/*
 * DeciDB: the sides of a BETWEEN, anchored at its keyword: the input, and the text from the lower bound through the
 * upper one (`lo AND hi`). A message quotes the clause as `input BETWEEN lo AND hi`.
 */
static PGNode *
noteDecideBetween(PGNode *between, YYLTYPE op, YYLTYPE input, YYLTYPE lower, YYLTYPE upper, core_yyscan_t yyscanner)
{
	YYLTYPE bounds = lower;

	bounds.end = upper.end;
	noteDecideSpan(yyscanner, op.start, PG_DECIDE_SPAN_BETWEEN_INPUT, input);
	noteDecideSpan(yyscanner, op.start, PG_DECIDE_SPAN_BETWEEN_BOUNDS, bounds);
	return between;
}

/*
 * DeciDB: fold a scope around the body it governs. WHEN applies first and PER
 * second, so PER is the outer node. PER ROW is the default written out: it names
 * no key, but it keeps a node of its own, so the clause follows the scoping
 * language like every other spelling.
 */
static PGNode *
applyDecideScope(PGNode *scope_node, PGNode *body)
{
	PGDecideScope *scope = (PGDecideScope *) scope_node;

	if (scope->when)
	{
		((PGAExpr *) scope->when)->lexpr = body;
		body = scope->when;
	}
	if (scope->per == PG_DECIDE_PER_ALL || scope->per == PG_DECIDE_PER_KEY)
		body = (PGNode *) makeSimpleAExpr(PG_AEXPR_SCOPE_PER, "scope_per", body,
										  (PGNode *) scope->key, scope->location);
	else if (scope->per == PG_DECIDE_PER_ROW)
		body = (PGNode *) makeSimpleAExpr(PG_AEXPR_SCOPE_PER_ROW, "scope_per_row", body,
										  NULL, scope->location);
	return body;
}

/*
 * DeciDB: a relation-qualified reducer, sum(D: expr) or sum(D, T: expr). Every
 * item of the qualifier must be a bare relation name; the binder resolves them.
 */
static PGNode *
makeQualifiedReducer(PGList *funcname, PGList *qualifier, PGList *args,
					 int location, int qualifier_location, int colon_location,
					 core_yyscan_t yyscanner)
{
	PGListCell *lc;

	foreach(lc, qualifier)
	{
		if (!IsA((PGNode *) lfirst(lc), PGColumnRef))
			ereport(ERROR,
					(errcode(PG_ERRCODE_SYNTAX_ERROR),
					 errmsg("the qualifier of a reducer must be a relation name or alias, as in sum(D: ...)"),
					 parser_errposition(qualifier_location)));
	}
	return (PGNode *) makeSimpleAExpr(PG_AEXPR_QUALIFIED_REDUCER, "qualified_reducer",
									  (PGNode *) makeFuncCall(funcname, args, location),
									  (PGNode *) qualifier, colon_location);
}

static PGNode *
makeAndExpr(PGNode *lexpr, PGNode *rexpr, int location)
{
	PGNode	   *lexp = lexpr;

	/* Look through AEXPR_PAREN nodes so they don't affect flattening */
	while (IsA(lexp, PGAExpr) &&
		   ((PGAExpr *) lexp)->kind == AEXPR_PAREN)
		lexp = ((PGAExpr *) lexp)->lexpr;
	/* Flatten "a AND b AND c ..." to a single PGBoolExpr on sight */
	if (IsA(lexp, PGBoolExpr))
	{
		PGBoolExpr *blexpr = (PGBoolExpr *) lexp;

		if (blexpr->boolop == PG_AND_EXPR)
		{
			blexpr->args = lappend(blexpr->args, rexpr);
			return (PGNode *) blexpr;
		}
	}
	return (PGNode *) makeBoolExpr(PG_AND_EXPR, list_make2(lexpr, rexpr), location);
}

static PGNode *
makeOrExpr(PGNode *lexpr, PGNode *rexpr, int location)
{
	PGNode	   *lexp = lexpr;

	/* Look through AEXPR_PAREN nodes so they don't affect flattening */
	while (IsA(lexp, PGAExpr) &&
		   ((PGAExpr *) lexp)->kind == AEXPR_PAREN)
		lexp = ((PGAExpr *) lexp)->lexpr;
	/* Flatten "a OR b OR c ..." to a single PGBoolExpr on sight */
	if (IsA(lexp, PGBoolExpr))
	{
		PGBoolExpr *blexpr = (PGBoolExpr *) lexp;

		if (blexpr->boolop == PG_OR_EXPR)
		{
			blexpr->args = lappend(blexpr->args, rexpr);
			return (PGNode *) blexpr;
		}
	}
	return (PGNode *) makeBoolExpr(PG_OR_EXPR, list_make2(lexpr, rexpr), location);
}

static PGNode *
makeNotExpr(PGNode *expr, int location)
{
	return (PGNode *) makeBoolExpr(PG_NOT_EXPR, list_make1(expr), location);
}

/* Separate PGConstraint nodes from COLLATE clauses in a */
static void
SplitColQualList(PGList *qualList,
				 PGList **constraintList, PGCollateClause **collClause,
				 core_yyscan_t yyscanner)
{
	PGListCell   *cell;
	PGListCell   *prev;
	PGListCell   *next;

	*collClause = NULL;
	prev = NULL;
	for (cell = list_head(qualList); cell; cell = next)
	{
		PGNode   *n = (PGNode *) lfirst(cell);

		next = lnext(cell);
		if (IsA(n, PGConstraint))
		{
			/* keep it in list */
			prev = cell;
			continue;
		}
		if (IsA(n, PGCollateClause))
		{
			PGCollateClause *c = (PGCollateClause *) n;

			if (*collClause)
				ereport(ERROR,
						(errcode(PG_ERRCODE_SYNTAX_ERROR),
						 errmsg("multiple COLLATE clauses not allowed"),
						 parser_errposition(c->location)));
			*collClause = c;
		}
		else
			elog(ERROR, "unexpected node type %d", (int) n->type);
		/* remove non-Constraint nodes from qualList */
		qualList = list_delete_cell(qualList, cell, prev);
	}
	*constraintList = qualList;
}

/*
 * Process result of ConstraintAttributeSpec, and set appropriate bool flags
 * in the output command node.  Pass NULL for any flags the particular
 * command doesn't support.
 */
static void
processCASbits(int cas_bits, int location, const char *constrType,
			   bool *deferrable, bool *initdeferred, bool *not_valid,
			   bool *no_inherit, core_yyscan_t yyscanner)
{
	/* defaults */
	if (deferrable)
		*deferrable = false;
	if (initdeferred)
		*initdeferred = false;
	if (not_valid)
		*not_valid = false;

	if (cas_bits & (CAS_DEFERRABLE | CAS_INITIALLY_DEFERRED))
	{
		if (deferrable)
			*deferrable = true;
		else
			ereport(ERROR,
					(errcode(PG_ERRCODE_FEATURE_NOT_SUPPORTED),
					 /* translator: %s is CHECK, UNIQUE, or similar */
					 errmsg("%s constraints cannot be marked DEFERRABLE",
							constrType),
					 parser_errposition(location)));
	}

	if (cas_bits & CAS_INITIALLY_DEFERRED)
	{
		if (initdeferred)
			*initdeferred = true;
		else
			ereport(ERROR,
					(errcode(PG_ERRCODE_FEATURE_NOT_SUPPORTED),
					 /* translator: %s is CHECK, UNIQUE, or similar */
					 errmsg("%s constraints cannot be marked DEFERRABLE",
							constrType),
					 parser_errposition(location)));
	}

	if (cas_bits & CAS_NOT_VALID)
	{
		if (not_valid)
			*not_valid = true;
		else
			ereport(ERROR,
					(errcode(PG_ERRCODE_FEATURE_NOT_SUPPORTED),
					 /* translator: %s is CHECK, UNIQUE, or similar */
					 errmsg("%s constraints cannot be marked NOT VALID",
							constrType),
					 parser_errposition(location)));
	}

	if (cas_bits & CAS_NO_INHERIT)
	{
		if (no_inherit)
			*no_inherit = true;
		else
			ereport(ERROR,
					(errcode(PG_ERRCODE_FEATURE_NOT_SUPPORTED),
					 /* translator: %s is CHECK, UNIQUE, or similar */
					 errmsg("%s constraints cannot be marked NO INHERIT",
							constrType),
					 parser_errposition(location)));
	}
}

/*----------
 * Recursive view transformation
 *
 * Convert
 *
 *     CREATE RECURSIVE VIEW relname (aliases) AS query
 *
 * to
 *
 *     CREATE VIEW relname (aliases) AS
 *         WITH RECURSIVE relname (aliases) AS (query)
 *         SELECT aliases FROM relname
 *
 * Actually, just the WITH ... part, which is then inserted into the original
 * view as the query.
 * ----------
 */
static PGNode *
makeRecursiveViewSelect(char *relname, PGList *aliases, PGNode *query)
{
	PGSelectStmt *s = makeNode(PGSelectStmt);
	PGWithClause *w = makeNode(PGWithClause);
	PGCommonTableExpr *cte = makeNode(PGCommonTableExpr);
	PGList	   *tl = NIL;
	PGListCell   *lc;

	/* create common table expression */
	cte->ctename = relname;
	cte->aliascolnames = aliases;
	cte->ctequery = query;
	cte->location = -1;

	/* create WITH clause and attach CTE */
	w->recursive = true;
	w->ctes = list_make1(cte);
	w->location = -1;

	/* create target list for the new SELECT from the alias list of the
	 * recursive view specification */
	foreach (lc, aliases)
	{
		PGResTarget *rt = makeNode(PGResTarget);

		rt->name = NULL;
		rt->indirection = NIL;
		rt->val = makeColumnRef(strVal(lfirst(lc)), NIL, -1, 0);
		rt->location = -1;

		tl = lappend(tl, rt);
	}

	/* create new SELECT combining WITH clause, target list, and fake FROM
	 * clause */
	s->withClause = w;
	s->targetList = tl;
	s->fromClause = list_make1(makeRangeVar(NULL, relname, -1));

	return (PGNode *) s;
}

/* parser_init()
 * Initialize to parse one query string
 */
void
parser_init(base_yy_extra_type *yyext)
{
	yyext->parsetree = NIL;		/* in case grammar forgets to set it */
}

